import Foundation

/// Represents a week's schedule generated by the agent
struct Week: Codable {
    let version: String
    let weekStartDate: Date
    let weekEndDate: Date
    let generatedAt: Date
    let events: [Event]

    /// Groups events by day for display
    func eventsByDay() -> [Date: [Event]] {
        let calendar = Calendar.current
        var grouped: [Date: [Event]] = [:]

        for event in events {
            let dayStart = calendar.startOfDay(for: event.startTime)
            grouped[dayStart, default: []].append(event)
        }

        // Sort events within each day by start time
        for (day, dayEvents) in grouped {
            grouped[day] = dayEvents.sorted { $0.startTime < $1.startTime }
        }

        return grouped
    }

    /// Returns array of 7 dates (Mon-Sun) for the week
    func weekDays() -> [Date] {
        let calendar = Calendar.current
        var days: [Date] = []

        for i in 0..<7 {
            if let day = calendar.date(byAdding: .day, value: i, to: weekStartDate) {
                days.append(calendar.startOfDay(for: day))
            }
        }

        return days
    }
}
